-- Dedicated project only; every fixture and session is rolled back.
begin;
do $$ declare owner_id uuid:=gen_random_uuid();employee uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();tenant uuid;a uuid;b uuid;sid uuid:=gen_random_uuid();old_sid uuid;denied boolean;w uuid;runid uuid:=gen_random_uuid();campaign uuid;version_time timestamptz;begin
 insert into auth.users(id,email) values(owner_id,'v5-owner-'||owner_id||'@fixture.invalid');select tenant_id into tenant from public.profiles where id=owner_id;
 insert into public.tenant_invites(tenant_id,email,role,can_publish,password_change_required,full_name) values(tenant,'v5-editor-'||employee||'@fixture.invalid','editor',false,true,'V5 editor fixture');
 insert into auth.users(id,email,raw_user_meta_data) values(employee,'v5-editor-'||employee||'@fixture.invalid','{"role":"super_admin"}');
 if not exists(select 1 from public.profiles where id=employee and tenant_id=tenant and role='editor' and password_change_required) then raise exception 'Trusted employee enrollment failed';end if;
 insert into auth.sessions(id,user_id,created_at,updated_at) values(sid,employee,clock_timestamp(),clock_timestamp());
 set local role service_role;
 if public.validate_actor_session(employee,sid,false) or not public.validate_actor_session(employee,sid,true) then raise exception 'Temporary credential escaped first-login restriction';end if;
 perform public.record_signin_activity(employee,sid);reset role;
 perform public.complete_employee_password_change(employee);
 if public.validate_actor_session(employee,sid,false) then raise exception 'Password change retained the prior session';end if;
 old_sid:=sid;sid:=gen_random_uuid();insert into auth.sessions(id,user_id,created_at,updated_at) values(sid,employee,clock_timestamp(),clock_timestamp());
 if not public.validate_actor_session(employee,sid,false) then raise exception 'Fresh employee session denied';end if;
 insert into public.articles(tenant_id,owner_id,assigned_to,title,content) values(tenant,owner_id,employee,'Assigned article','<p>Assigned original source with enough detail for editorial review.</p>') returning id into a;
 insert into public.articles(tenant_id,owner_id,title,content) values(tenant,owner_id,'Private owner article','<p>Owner-only original.</p>') returning id into b;
 insert into auth.users(id,email) values(outsider,'v5-outsider-'||outsider||'@fixture.invalid');
 insert into public.articles(tenant_id,owner_id,title,content) select tenant_id,outsider,'Other tenant','<p>Other tenant private content.</p>' from public.profiles where id=outsider;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',employee,'session_id',sid,'role','authenticated')::text,true);set local role authenticated;
 if (select count(*) from public.articles)<>1 or (select id from public.articles limit 1)<>a then raise exception 'Assignment or tenant RLS leaked articles';end if;
 if (select count(*) from public.websites)<>0 or (select count(*) from public.campaigns)<>0 then raise exception 'Editor accessed publishing workspace data';end if;
 reset role;
 if private.actor_permission(employee,'articles.approve') or private.actor_permission(employee,'campaigns.launch') or private.actor_permission(employee,'users.create') then raise exception 'Editor inherited unsafe permission';end if;
 denied:=false;begin perform public.approve_article_version(employee,a,(select current_version_id from public.articles where id=a));exception when others then denied:=true;end;if not denied then raise exception 'Employee self-approved an article';end if;
 perform public.approve_article_version(owner_id,a,(select current_version_id from public.articles where id=a));
 if not exists(select 1 from public.articles where id=a and approved_version_id=current_version_id and status='approved') then raise exception 'Exact version approval failed';end if;
 insert into public.websites(tenant_id,owner_id,website_name,website_url,api_endpoint,cms_type,connection_status,permission_status) values(tenant,owner_id,'V5 transactional target','https://v5-fixture.publisher.org','https://v5-fixture.publisher.org/.well-known/guestpost','custom','connected','verified') returning id into w;
 insert into public.smoke_test_runs(id,tenant_id,initiated_by,article_id,target_website_id,reviewed_version_id,status) select runid,tenant,articles.owner_id,a,w,current_version_id,'awaiting_approval' from public.articles where id=a;
 select updated_at into version_time from public.articles where id=a;
 perform pg_temp.qualify_fixture(owner_id,w);
 campaign:=public.start_attributed_campaign(owner_id,a,version_time,'V5 transactional smoke',array[w],300,now(),'{}','manual',jsonb_build_object('smoke_run_id',runid));
 if not exists(select 1 from public.smoke_test_runs where id=runid and campaign_id=campaign and status='scheduled') then raise exception 'Atomic smoke scheduling failed';end if;
 denied:=false;begin perform public.start_attributed_campaign(owner_id,a,version_time,'Duplicate smoke',array[w],300,now(),'{}','manual',jsonb_build_object('smoke_run_id',runid));exception when others then denied:=true;end;if not denied then raise exception 'Smoke run launched twice';end if;
 perform public.approve_article_version(owner_id,b,(select current_version_id from public.articles where id=b));runid:=gen_random_uuid();
 insert into public.smoke_test_runs(id,tenant_id,initiated_by,article_id,target_website_id,reviewed_version_id,status) select runid,tenant,articles.owner_id,b,w,current_version_id,'awaiting_approval' from public.articles where id=b;
 update public.articles set content='<p>Changed after preflight review.</p>',status='draft',updated_at=clock_timestamp() where id=b returning updated_at into version_time;
 denied:=false;begin perform public.start_attributed_campaign(owner_id,b,version_time,'Stale smoke',array[w],300,now(),'{}','manual',jsonb_build_object('smoke_run_id',runid));exception when others then denied:=true;end;if not denied then raise exception 'Stale smoke review autoapproved edited content';end if;
 if (select status from public.articles where id=b)<>'draft' then raise exception 'Failed smoke launch approved content';end if;
 update public.articles set content='<p>Changed content after approval.</p>',status='draft',updated_at=clock_timestamp() where id=a;
 if exists(select 1 from public.articles where id=a and approved_version_id=current_version_id) then raise exception 'Editing retained approval';end if;
 perform public.update_employee_access(owner_id,employee,'editor',false,'V5 editor fixture','SEO',null);
 if public.validate_actor_session(employee,sid,false) then raise exception 'Suspension retained API access';end if;
 set local role authenticated;if (select count(*) from public.articles)<>0 then raise exception 'Suspended JWT retained REST data';end if;reset role;
 perform public.update_employee_access(owner_id,employee,'editor',true,'V5 editor fixture','SEO',null);
 if public.validate_actor_session(employee,sid,false) or public.validate_actor_session(employee,old_sid,false) then raise exception 'Reactivation revived old JWTs';end if;
 if has_table_privilege('anon','public.shared_reports','SELECT') or has_table_privilege('authenticated','private.provider_credentials','SELECT') or has_function_privilege('authenticated','public.read_provider_secret(uuid,text)','EXECUTE') or has_function_privilege('authenticated','public.complete_employee_password_change(uuid)','EXECUTE') then raise exception 'Public credential or share-token access';end if;
end $$;
rollback;
select 'passed' as result,'Employee enrollment, forced change, live sessions, RLS, tenant isolation, exact approval and credential privacy' as checks;
